type MailboxAddress = {
  name?: string;
  address: string;
};

type Thread = {
  id: string;
  messageIds: readonly string[];
  labelIds: readonly string[];
  subject: string;
  snippet: string;
  participants: readonly MailboxAddress[];
  lastMessageAt: string;
  unreadMessageCount: number;
  revision: string;
};

type Message = {
  readonly id: string;
  readonly threadId: string;
  readonly labelIds: readonly string[];
  readonly from: MailboxAddress;
  readonly to: readonly MailboxAddress[];
  readonly sentAt: string;
  readonly subject: string;
  readonly snippet: string;
  readonly bodyResourceId: string;
  readonly attachmentIds: readonly string[];
  readonly revision: string;
  readonly clientCommandId?: string;
};

type Label = {
  id: string;
  name: string;
  kind: 'system' | 'user';
  color?: string;
  revision: string;
};

type MailboxSnapshot = {
  mailboxId: string;
  syncCursor: string;
  threads: readonly Thread[];
  messages: readonly Message[];
  labels: readonly Label[];
  capturedAt: string;
};

type DraftAttachmentBase = {
  attachmentId: string;
  draftId: string;
  fileName: string;
  contentType: string;
  sizeBytes: number;
};

type DraftAttachment =
  | (DraftAttachmentBase & {
      status: 'selected';
      uploadedBytes: 0;
    })
  | (DraftAttachmentBase & {
      status: 'uploading' | 'processing';
      uploadSessionId: string;
      uploadedBytes: number;
    })
  | (DraftAttachmentBase & {
      status: 'ready';
      uploadSessionId: string;
      uploadedBytes: number;
      assetId: string;
      assetRevision: string;
    })
  | (DraftAttachmentBase & {
      status: 'failed';
      uploadSessionId?: string;
      uploadedBytes: number;
      failureCode: string;
      retryable: boolean;
    })
  | (DraftAttachmentBase & {
      status: 'blocked';
      uploadSessionId: string;
      uploadedBytes: number;
      assetId: string;
      failureCode: string;
    })
  | (DraftAttachmentBase & {
      status: 'canceled';
      uploadedBytes: number;
    });

type DraftContent = {
  to: readonly MailboxAddress[];
  cc: readonly MailboxAddress[];
  bcc: readonly MailboxAddress[];
  subject: string;
  bodyHtml: string;
  attachmentIds: readonly string[];
};

type DraftDocument = {
  draftId: string;
  mailboxId: string;
  threadId?: string;
  content: DraftContent;
  contentRevision: number;
  baseRemoteRevision: string | null;
  remoteRevision?: string;
  updatedAt: string;
};

type RemoteDraftRevision = {
  draftId: string;
  mailboxId: string;
  threadId?: string;
  content: DraftContent;
  revision: string;
  acknowledgedContentRevision?: number;
  updatedAt: string;
};

type CommandBase = {
  commandId: string;
  idempotencyKey: string;
  baseRevision: string | null;
  createdAt: string;
};

type OutboxCommand =
  | (CommandBase & {
      kind: 'draft.save';
      draftId: string;
      document: DraftDocument;
    })
  | (CommandBase & {
      kind: 'draft.send';
      draftId: string;
      expectedContentRevision: number;
      attachmentAssetIds: readonly string[];
    })
  | (CommandBase & {
      kind: 'thread.labels.set';
      threadId: string;
      addLabelIds: readonly string[];
      removeLabelIds: readonly string[];
    });

type PendingCommand = {
  command: OutboxCommand;
  status: 'queued' | 'submitting' | 'awaiting-delta' | 'conflict' | 'failed';
  attemptCount: number;
  retryAfter?: string;
  lastErrorCode?: string;
};

type MailboxProjection = {
  threadsById: Record<string, Thread>;
  messagesById: Record<string, Message>;
  labelsById: Record<string, Label>;
  remoteDraftsById: Record<string, RemoteDraftRevision>;
  syncCursor: string | null;
  phase: 'empty' | 'cached' | 'syncing' | 'fresh' | 'stale' | 'recovering';
};

type LocalIntentState = {
  draftsById: Record<string, DraftDocument>;
  attachmentsById: Record<string, DraftAttachment>;
  commandsById: Record<string, PendingCommand>;
};

type MailboxClientState = {
  projection: MailboxProjection;
  localIntent: LocalIntentState;
  view: {
    selectedThreadId?: string;
    activeLabelId?: string;
    query: string;
  };
  resources: {
    bodyCacheKeys: readonly string[];
    attachmentCacheKeys: readonly string[];
    localSearchVersion?: string;
  };
};
